import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, scale
  const pos = config.scenePosition || {};
  group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);

  if (pos.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.x = pos.rotationXYZ[0];
    group.rotation.y = pos.rotationXYZ[1];
    group.rotation.z = pos.rotationXYZ[2];
  }

  if (pos.scaleXYZ) {
    group.scale.x = pos.scaleXYZ[0];
    group.scale.y = pos.scaleXYZ[1];
    group.scale.z = pos.scaleXYZ[2];
  }

  // Create plane mesh with texture
  const geometry = new THREE.PlaneGeometry(1, 1);
  const texture = config.imageUrl ? ctx.textureLoader.load(config.imageUrl) : null;

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0 && ctx.fontAtlas) {
    const textSpec = config.textContent[0];
    const textMesh = ctx.fontAtlas.createText({
      text: textSpec.text || 'Pricing 1',
      fontSize: 0.34, // headline size from type scale
      fontFamily: 'Lora',
      fontWeight: 400,
      color: 0xe8ecf2, // paper color
    });
    group.add(textMesh);
  }

  // Apply cinematic primitives (none in this specification)
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    }
  }

  // Cleanup resources
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    if (texture) {
      texture.dispose();
    }
  };

  // Event handlers (none specified for this static node)
  group.userData.handlers = {};

  return group;
}
